     * of characters in one request - SpeakersPage's "Recharacterize all",
     * fire-and-forget (202 Accepted, no result body) via
     * jobs.Manager.EnqueueCharacterization rather than one blocking
     * POST .../characterize per character (see that method's own doc comment
     * for why: the browser's per-origin connection cap plus a page reload
     * mid-burst could otherwise silently drop whichever characters' requests
     * hadn't gone out yet). Unknown/already-deleted character ids are skipped,
     * not an error - a stale id in the client's own list (e.g. a character
     * merged/deleted by another tab moments earlier) shouldn't fail the rest
     * of the batch. Progress is observable the same way as any other
     * characterization - GET /api/jobs, and refetching this book's speaker
     * table once each one's task clears.
     */
    @POST("api/books/{id}/characters/characterize")
    suspend fun characterizeSpeakers(
        @Path("id") id: String,
        @Body body: CharacterIDsRequestDto,
    ): QueuedResponseDto

    /**
     * handleDedupeCharacters serves POST /api/books/{id}/characters/dedupe - the
     * Speakers page's "merge duplicate names" action (see dedupeCharacters),
     * replying with every merge it made. Attribution already avoids making new
     * duplicates (case-insensitive lookup, descriptions to roles, first names
     * folded into full ones as they appear); this cleans up a roster built
     * before that, or across chapters attributed out of order.
     */
    @POST("api/books/{id}/characters/dedupe")
    suspend fun dedupeCharacters(
        @Path("id") id: String,
    ): DedupeResponseDto

    /**
     * handleGenerateCharacterVoices batch-provisions a voice for every given
     * character in one request - SpeakersPage's "Generate all voices",
     * fire-and-forget (202 Accepted, no result body), the same rationale as
     * handleCharacterizeSpeakers: one request that survives the page closing,
     * not N blocking requests capped by the browser's own per-origin
     * connection limit.
     *
     * Each character's provisionCharacterVoice call runs as its own
     * jobs.Manager KindVoiceProvision task (see EnqueueVoiceProvision) rather
     * than a bare detached goroutine (an earlier version of this handler used
     * one): a goroutine calling straight into the TTS worker bypasses
     * poolGeneration's own concurrency limit and, more importantly, the
     * worker's poolGeneration/poolLLM mutual exclusion (see worker's own
     * fill) that keeps this app's two GPU-bound subsystems - the TTS worker
     * and the in-process speakerattr LLM - from running at the same time and
     * competing for VRAM. EnqueueVoiceProvision's own doc comment covers why
     * this is poolGeneration rather than poolLLM despite
     * provisionCharacterVoice itself enqueuing a KindSpeakerCharacterization
     * (poolLLM) task internally for an uncharacterized character. Already-
     * provisioned characters no-op harmlessly, same as the single-character
     * button - see provisionCharacterVoice's own doc comment; a character with
     * no dialogue/description attributed yet now still gets characterized
     * (from its name alone) and provisioned like any other, rather than
     * silently no-opping. Unknown/already-deleted
     * character ids are skipped, not an error, same reasoning as
     * handleCharacterizeSpeakers.
     */
    @POST("api/books/{id}/characters/generate-voice")
    suspend fun generateCharacterVoices(
        @Path("id") id: String,
        @Body body: CharacterIDsRequestDto,
    ): QueuedResponseDto

    /**
     * handleRegenerateCharacterVoices batch-forces a fresh reference-clip
     * render for every given character in one request - SpeakersPage's
     * "Regenerate all voices", distinct from handleGenerateCharacterVoices:
     * that one only provisions characters with no voice yet (idempotent,
     * no-ops on an already-provisioned one), this one re-renders regardless of
     * whether a cached ref already exists - see regenerateCharacterVoice. Same
     * EnqueueVoiceProvision/KindVoiceProvision shape and rationale as
     * handleGenerateCharacterVoices (its own doc comment covers the
     * poolGeneration-not-poolLLM reasoning, which applies identically here -
     * regenerateCharacterVoice can also enqueue a KindSpeakerCharacterization
     * task internally, for a character with no voice yet at all).
     */
    @POST("api/books/{id}/characters/regenerate-voice")
    suspend fun regenerateCharacterVoices(
        @Path("id") id: String,
        @Body body: CharacterIDsRequestDto,
    ): QueuedResponseDto

    /**
     * handleDeleteCharacter removes one character entirely - a scalpel next
     * to handleDeleteBookSpeakerData's sledgehammer, for cleaning up a single
     * bad attribution (a name that was never really a character - a stray
     * first-person pronoun, a generic descriptive phrase, a one-off
     * hallucination) without resetting the whole roster. Every paragraph in
     * *this* book currently attributed to them reverts to "Unknown", not ""
     * (Narrator) - see Store.ReassignCharacterSpeaker's own doc comment for
     * why: these paragraphs are still real quoted dialogue, just no longer
     * attributed to this character, and "Narrator" is reserved exclusively
     * for actual narration. Paragraphs tagged as describing them lose that
     * tag. Scoped to this book only; their identity/Summary,
     * every clone model's voice assignment, and every voice preset
     * auto-created for them (+ cached reference clip) are deleted for their
     * whole series scope, same split as handleDeleteBookSpeakerData.
     */
    @DELETE("api/books/{id}/characters/{characterId}")
    suspend fun deleteCharacter(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
    ): Unit

    /**
     * handleSetCharacterAliases replaces one character's aliases (store.
     * Character.Aliases) - other names they go by, which attribution folds
     * back into their name and reads in speech tags ("Albert said"). 400 for
     * an alias that names no single person (a group like "Bert and Sid", a
     * non-answer like "No one"); 409 for one that's already another valid
     * character's name or alias in this series (merge them instead).
     */
    @PUT("api/books/{id}/characters/{characterId}/aliases")
    suspend fun setCharacterAliases(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: SetCharacterAliasesRequestDto,
    ): AliasesResponseDto

    /**
     * handleCharacterAppearances lists every paragraph a character speaks,
     * across every book in their series (see store.SeriesScope) - backing a
     * "where does this character show up" view. bookID in the path is just
     * how the character is reached (matching every other .../characters/{id}
     * route); the character's own scope, not that one book, decides which
     * books are actually searched.
     */
    @GET("api/books/{id}/characters/{characterId}/appearances")
    suspend fun characterAppearances(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
    ): List<SpeakerAppearanceDto>

    /**
     * handleCharacterizeSpeaker force re-runs characterization for one
     * character - the Speakers page's own (and the reader-view annotation
     * legend's own) explicit "Regenerate" button, distinct from
     * provisionCharacterVoice's own lazy, characterize-once-ever behavior.
     * Unlike that path, this always re-runs even if char.Summary is already
     * set (a deliberate "redo this with a fuller sample now that there's more
     * dialogue" ask - see backend/CLAUDE.md's "Speaker attribution" section).
     *
     * Dispatched through jobs.Manager.RunCharacterization - same
     * KindSpeakerCharacterization task shape (and same TierUrgent/poolLLM
     * admission, and dedup-by-characterID against an already-in-flight run)
     * its own batch sibling handleCharacterizeSpeakers and the lazy path
     * (ensureCharacterized) both already use - rather than calling
     * characterizeVoice directly against the request's own context, which an
     * earlier version of this handler did: that bypassed the job queue
     * entirely, so a manual "Regenerate" click showed up nowhere on the Jobs
     * dashboard, couldn't join (or be joined by) a concurrent run for the same
     * character, and - the sharper bug - never respected poolGeneration/
     * poolLLM's mutual exclusion (see internal/jobs' own "Layout" section in
     * backend/CLAUDE.md), so it could run the speakerattr LLM at the exact
     * same time as ordinary TTS generation, the two GPU-bound subsystems this
     * app is otherwise careful to never let contend for VRAM at once.
     * RunCharacterization still blocks this request until the task finishes
     * (a single character's own characterization is one short LLM call, the
     * same "fine to hold the connection open" reasoning EnqueueAttribution's
     * own doc comment gives for why *that* one doesn't), so the response body
     * (summary/voiceInvalidated) is unchanged.
     *
     * See recharacterizeAndInvalidate for what happens after a successful
     * re-characterization (every clone model's assigned voice preset for the
     * character gets invalidated, not just rebuilt eagerly).
     */
    @POST("api/books/{id}/characters/{characterId}/characterize")
    suspend fun characterizeSpeaker(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
    ): CharacterizeResponseDto

    /**
     * handlePreviewCharacterization runs a character's characterization
     * (castCharacter) and returns the casting without storing it, so a change
     * to the prompts or the retrieval can be judged against the stored casting
     * without discarding anyone's voice or audio. ?temp= sets the casting
     * call's sampling temperature and ?lookup=0 casts without the
     * book lookups.
     */
    @POST("api/books/{id}/characters/{characterId}/characterize/preview")
    suspend fun previewCharacterization(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Query("lookup") lookup: String? = null,
        @Query("temp") temp: String? = null,
    ): CharacterizePreviewResponseDto

    /**
     * handleGenerateCharacterVoice force-provisions a voice for one character
     * right now, rather than waiting for the lazy path
     * (jobs.Manager.provisionMissingCharacterVoices) to trigger it the next
     * time their dialogue is actually generated - the Speakers page's own
     * "Generate voice" button, for previewing/setting up a character's voice
     * ahead of time. Idempotent: if they already have one for this book's
     * clone model, provisionCharacterVoice's own fast path just returns it
     * unchanged. 409 if there still isn't enough dialogue to characterize
     * them from yet (provisionCharacterVoice returns "", nil in that case,
     * same as the lazy path silently no-ops on).
     */
    @POST("api/books/{id}/characters/{characterId}/generate-voice")
    suspend fun generateCharacterVoice(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
    ): GenerateVoiceResponseDto

    /**
     * handleSetCharacterInvalid marks (or unmarks) a character as invalid -
     * not a real speaker, so attribution stops creating/assigning the name
     * (see store.Character.Invalid). Non-destructive: the paragraphs already
     * attributed to them, their summary, and their voice assignments are all
     * left alone, so unmarking restores them exactly - Auto Split
     * (handleReattributeSpeaker, which also sets this flag) is what actually
     * moves their existing lines elsewhere.
     */
    @PUT("api/books/{id}/characters/{characterId}/invalid")
    suspend fun setCharacterInvalid(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: SetCharacterInvalidRequestDto,
    ): Unit

    /**
     * handleMergeCharacter folds one character into another: every paragraph
     * in their series currently attributed to them is reattributed to
     * req.TargetName instead of reverting to blank, and their own identity/
     * voice/presets are deleted for their whole series scope (see
     * deleteCharacterIdentity) - for when attribution split one person into
     * two rows (a variant spelling canonicalizeSpeakerNames didn't catch, or
     * a misattribution like a character's own name appearing as a vocative
     * in someone else's line - see backend/CLAUDE.md's "Speaker attribution"
     * section), or turns out to have just been the narrator all along.
     * Unlike handleDeleteCharacter (which always reassigns to "Unknown" -
     * see its own doc comment), this lets the caller explicitly choose
     * "Narrator" as the target too: a deliberate reader assertion ("this
     * really was narration, not a real speaker") is different from simply
     * removing a bad character with no replacement judgment made either way.
     * Both are thin wrappers over the same two steps (Store.
     * ReassignCharacterSpeaker + deleteCharacterIdentity) with a different
     * fixed/caller-supplied target; merging into another named character
     * additionally registers it as a real character first if it wasn't one
     * already (UpsertCharacter is idempotent either way - see
     * handleListSpeakers' own comment on a raw paragraph speaker that never
     * got registered).
     */
    @POST("api/books/{id}/characters/{characterId}/merge")
    suspend fun mergeCharacter(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: MergeCharacterRequestDto,
    ): Unit

    /**
     * handleRenameCharacter renames one character series-wide
     * (renameCharacter: their lines, description tags, speaker corrections,
     * summary notes, the setting's narrator, auto-named voice presets), keeping
     * their voice, casting and audio. The old name becomes an alias, so
     * attribution folds it back in if the text or the model still uses it -
     * unless it names no single person ("Protagonist", "the other noble,
     * Charles"). 400 for a name that isn't one person's (a group, a
     * non-answer, Narrator/Unknown); 409 when another character in the series
     * already has it as a name or alias (merge them instead).
     */
    @PUT("api/books/{id}/characters/{characterId}/name")
    suspend fun renameCharacter(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: RenameCharacterRequestDto,
    ): Unit

    /**
     * handleSetCharacterPronouns sets one character's pronouns (store.
     * Character.Pronouns), which attribution shows in "Known characters" and
     * characterization takes as its gender signal. Doesn't re-characterize
     * on its own - the Speakers page's "Regenerate" does that. 400 for a
     * value that isn't one of the known sets.
     */
    @PUT("api/books/{id}/characters/{characterId}/pronouns")
    suspend fun setCharacterPronouns(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: SetCharacterPronounsRequestDto,
    ): PronounsResponseDto

    /**
     * handleSetCharacterRole marks (or unmarks) a character as a generic role
     * label (store.Character.IsRole) - several unnamed people of one kind
     * ("Guard", "Woman") rather than one individual. Attribution lists it as
     * "[role]", characterization casts the type, and pronouns aren't tracked
     * for it. Nothing else changes: its lines, voice and aliases stay.
     */
    @PUT("api/books/{id}/characters/{characterId}/role")
    suspend fun setCharacterRole(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: SetCharacterRoleRequestDto,
    ): Unit

    /**
     * handleSetCharacterVoice assigns (or, with "", clears) a character's own
     * narration voice - a character with no voice assigned still narrates in
     * the book's own voice even when book.MultiVoice is on (see
     * internal/narration.Resolver). The assignment is scoped to the *book's
     * own* resolved clone model (see store.Character's doc comment) - a
     * reader manually assigning a voice through this book's speaker table sets
     * what that character sounds like specifically when narrated through this
     * book's model, not through every clone model a character might ever be
     * narrated with.
     */
    @PUT("api/books/{id}/characters/{characterId}/voice")
    suspend fun setCharacterVoice(
        @Path("id") id: String,
        @Path("characterId") characterId: String,
        @Body body: SetCharacterVoiceRequestDto,
    ): Unit

    @Streaming
    @GET("api/books/{id}/cover")
    suspend fun getCover(
        @Path("id") id: String,
    ): ResponseBody

    @GET("api/books/{id}/exports")
    suspend fun listExports(
        @Path("id") id: String,
    ): List<BookExportDto>

    /**
     * handleCreateExport queues an export as a job-queue task (a Jobs-page
     * row, Kind "pipeline_export") - rebuilding it if one with the same
     * settings already exists. Unless AsIs, the task first renders the
     * chapters' missing audio (jobs.Manager.RenderChapters) and waits for it.
     * Progress and the result show up on the bookExports live topic.
     */
    @POST("api/books/{id}/exports")
    suspend fun createExport(
        @Path("id") id: String,
        @Body body: CreateExportRequestDto,
    ): QueuedResponseDto

    /**
     * handleDeleteExport removes an export's file, or cancels its task.
     */
    @DELETE("api/books/{id}/exports/{exportId}")
    suspend fun deleteExport(
        @Path("id") id: String,
        @Path("exportId") exportId: String,
    ): Unit

    @Streaming
    @GET("api/books/{id}/exports/{exportId}/file")
    suspend fun getExportFile(
        @Path("id") id: String,
        @Path("exportId") exportId: String,
    ): ResponseBody

    /**
     * handleGenerateBook enqueues background TTS generation for every chapter
     * in a book at once - the library page's own "Generate audio" -> "All"
     * button (LibraryPage.tsx), for a reader who wants a whole book ready to
     * listen to without opening it chapter by chapter first.
     *
     * A single call into jobs.Manager.EnqueueBookGenerate, not a loop over
     * every chapter here: that whole-book walk (and its own cancelability) now
     * lives on the Manager side, as one cancelable group task rather
     * than this handler pushing N independent per-chapter tasks with no
     * single handle to stop them all at once - see EnqueueBookGenerate's own
     * doc comment. Fire-and-forget either way: this never itself blocks on an
     * actual TTS render or LLM call the way a preprocessing phase does, and
     * calling it twice in a row, or alongside a reader actively reading the
     * book, just re-enqueues whatever isn't already ready/generating,
     * harmlessly (EnqueueBookGenerate's own task is idempotent per book, same
     * as EnqueueChapter always was per chapter).
     */
    @POST("api/books/{id}/generate")
    suspend fun generateBook(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleGenerateRemaining enqueues background TTS generation for every
     * paragraph in a book from its current stored reading position
     * (store.Book.PosChapterIdx/PosParagraphIdx) through the end of the book -
     * the "Remaining" option on the library page's "Generate audio" button
     * (LibraryPage.tsx), alongside handleGenerateBook's "All" option. Position
     * is read server-side rather than taken from the request body: it's the
     * same value GET /api/books already returns per book, so a caller (the
     * library page, or the Android app's own long-press equivalent) needs
     * nothing beyond the book ID to mean "the rest of this book, from wherever
     * I've actually gotten to". See jobs.Manager.EnqueueRemaining.
     */
    @POST("api/books/{id}/generate-remaining")
    suspend fun generateRemaining(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleCancelBookJobs cancels every queued and in-flight task working on
     * one book - the library card's "Cancel jobs" button. See
     * jobs.Manager.CancelBook.
     */
    @DELETE("api/books/{id}/jobs")
    suspend fun cancelBookJobs(
        @Path("id") id: String,
    ): CanceledCountResponseDto

    @GET("api/books/{id}/lexicon")
    suspend fun listLexicon(
        @Path("id") id: String,
    ): List<LexiconEntryDto>

    /**
     * handleUpsertLexicon adds a pronunciation rule to the book's series, or
     * replaces the one for the same term (case-insensitively), then clears
     * generated audio for every paragraph in the series that the old or new
     * rule matches, so it's re-rendered with the new pronunciation.
     */
    @PUT("api/books/{id}/lexicon")
    suspend fun upsertLexicon(
        @Path("id") id: String,
        @Body body: UpsertLexiconRequestDto,
    ): IdResponseDto

    /**
     * handleLexiconMatches reports what a rule - saved or not - matches in this
     * book, so the editor can show it before saving.
