    @POST("api/books/{id}/lexicon/matches")
    suspend fun lexiconMatches(
        @Path("id") id: String,
        @Body body: UpsertLexiconRequestDto,
    ): LexiconMatchesDto

    /**
     * handlePreviewLexicon renders a rule - saved or not yet saved - in the
     * book's own narrator voice and clone model, so a listener can hear a
     * respelling before committing to it (and regenerating every line it
     * matches). Speaks the first sentence in the book the rule matches, with
     * the rule applied, falling back to the replacement alone.
     */
    @Streaming
    @POST("api/books/{id}/lexicon/preview")
    suspend fun previewLexicon(
        @Path("id") id: String,
        @Body body: UpsertLexiconRequestDto,
    ): ResponseBody

    @GET("api/books/{id}/lexicon/suggestions")
    suspend fun lexiconSuggestions(
        @Path("id") id: String,
    ): List<LexiconSuggestionDto>

    /**
     * handleDeleteLexicon removes a pronunciation rule and clears generated
     * audio for every paragraph in its series that the rule matched.
     */
    @DELETE("api/books/{id}/lexicon/{entryId}")
    suspend fun deleteLexicon(
        @Path("id") id: String,
        @Path("entryId") entryId: String,
    ): Unit

    /**
     * handleLookahead keeps some runway of generated audio ahead of wherever
     * the reader currently is, spanning into later chapters as needed rather
     * than stopping at the current chapter's end - see
     * jobs.Manager.EnqueueLookahead.
     */
    @POST("api/books/{id}/lookahead")
    suspend fun lookahead(
        @Path("id") id: String,
        @Body body: LookaheadRequestDto,
    ): QueuedResponseDto

    /**
     * handleBookManifest returns a book's offline-sync root hash plus its
     * chapter hashes. `?chapters=0,3,7` limits it to those chapters (unknown
     * indexes are just absent from the result) - a client only ever holds a
     * few chapters of a book offline, so it asks for just what it has; the
     * root then covers only that subset, which is still exactly what it needs
     * to compare against. Without the parameter, every chapter is included.
     *
     * Chapter hashes come from the stored tree (store.SyncTreeNodes) wherever
     * their inputs haven't moved, so an unchanged book costs a fingerprint
     * query plus two small reads, not a buildChapter per chapter - see "The
     * stored tree" above.
     */
    @GET("api/books/{id}/manifest")
    suspend fun bookManifest(
        @Path("id") id: String,
        @Query("chapters") chapters: String? = null,
    ): BookManifestDto

    /**
     * handleListParagraphEdits serves GET /api/books/{id}/paragraph-edits
     * (?field=speaker|emotion|scare_quote, default all): every manual
     * correction the reader made to the book's machine-labeled speakers,
     * emotions and scare-quote flags, in
     * reading order - the reference a change to attribution or the emotion
     * pass is scored against.
     */
    @GET("api/books/{id}/paragraph-edits")
    suspend fun listParagraphEdits(
        @Path("id") id: String,
        @Query("field") field: ParagraphEditField? = null,
    ): ParagraphEditsResponseDto

    @GET("api/books/{id}/position")
    suspend fun getPosition(
        @Path("id") id: String,
    ): PositionDto

    @PUT("api/books/{id}/position")
    suspend fun updatePosition(
        @Path("id") id: String,
        @Body body: PositionDto,
    ): Unit

    /**
     * handlePreprocessBook kicks off the preprocessing pipeline for the whole
     * book (see jobs.Manager.EnqueuePipeline) and returns
     * immediately (202) - the same fire-and-forget shape as
     * handleAttributeSpeakers/handleTagDirections, for the same reason: a
     * whole book can take anywhere from minutes to hours to fully attribute/
     * characterize/provision/tag, so nothing should hold an HTTP request (or a
     * browser connection) open for it. Progress is observable the same way
     * running each phase's own buttons individually already is - via GET
     * /api/jobs (each chapter/character's own attribution/characterization/
     * direction/provision task appears there as it's dispatched, same Kinds
     * as the single-item buttons use), by refetching the book's speaker table
     * as chapters/characters complete, and via bookSummaryDTO.Preprocessing
     * (see isPreprocessing) for a simple whole-book "still running" indicator
     * - the library page polls this to show a spinner over the cover for as
     * long as it's true.
     *
     * Rejects (409) a second call for a book that already has one of these
     * running - see jobs.ErrPipelineAlreadyRunning.
     *
     * chapters is listed once here, before any phase is even enqueued, and
     * shared unchanged by every chapter-scoped phase below (see their own doc comments for why that
     * staleness is safe) - mirroring the one piece of shared, hoisted state
     * the old single-goroutine runBookPipeline used to keep across its own
     * four inline phases; a failure listing it aborts the whole preprocessing
     * request up front (500) rather than starting phase 1 with nothing to do.
     */
    @POST("api/books/{id}/preprocess")
    suspend fun preprocessBook(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handlePreprocessSeries preprocesses every book of the book's series, one
     * at a time in series order: a book's pipeline (handlePreprocessBook's) is
     * queued only once the one before it has finished, so each book is
     * attributed and cast against the roster the earlier books left - the
     * series shares one (store.SeriesScope). One job-queue row (a
     * jobs.BulkGroup, Kind "pipeline_series_preprocess", on the series' first
     * book); each book's own phases appear under it as that book's turn comes.
     * Promoting the row promotes each book's phases as its turn comes (and
     * the one in progress). Cancelling the row stops the run before the next book - the book in
     * progress carries on unless cancelled itself. A book already
     * preprocessing is waited for, not restarted. 202, 409 for a book in no
     * series.
     */
    @POST("api/books/{id}/preprocess-series")
    suspend fun preprocessSeries(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleMarkRead marks a book read or unread from the libraries' own
     * button, without opening it: read moves the saved position to the book's
     * last paragraph, unread back to its start (see Store.MarkBookRead).
     */
    @PUT("api/books/{id}/read")
    suspend fun markRead(
        @Path("id") id: String,
        @Body body: MarkReadRequestDto,
    ): Unit

    /**
     * handleGetBookRecap serves GET /api/books/{id}/recap.
     */
    @GET("api/books/{id}/recap")
    suspend fun getBookRecap(
        @Path("id") id: String,
    ): BookRecapResponseDto

    /**
     * handlePrepareBookRecap serves POST /api/books/{id}/recap: queues the
     * recap for the book's saved reading position (the pipeline_recap job) and
     * answers 202 with how many it queued - 0 when the book already has one
     * for that position, or there is nothing to recap there. ?force=true
     * writes it again regardless. The bookRecap live topic carries the result.
     */
    @POST("api/books/{id}/recap")
    suspend fun prepareBookRecap(
        @Path("id") id: String,
        @Query("force") force: String? = null,
    ): QueuedResponseDto

    /**
     * handleGetBookRecapAudio serves GET /api/books/{id}/recap/audio - the
     * recap as spoken (bookRecapDTO.AudioURL).
     */
    @Streaming
    @GET("api/books/{id}/recap/audio")
    suspend fun getBookRecapAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleResetPass is POST /api/books/{id}/reset/{pass} - the Speakers
     * page's per-column reset buttons: clears one pass across the whole book as
     * though it had never run, and deletes whatever generated audio it made
     * stale. pass is a bulk action name:
     *   - "attribution"/"scare_quote"/"direction"/"pronunciation":
     *     the paragraph data that pass wrote plus its chapters.passes flag (see
     *     store.PassResets), invalidating audio for just the paragraphs whose
     *     narration it changed (and their scare-quote merge groups). The
     *     character roster is left alone - "Delete speaker data" covers that.
     *   - "ambience": every music region (and its clip, and its lighting),
     *     unsetting passes.ambience and passes.lighting
     *   - "lighting": every music region's lighting cue, unsetting
     *     passes.lighting - the music is kept
     *   - "music_generation": every music region's clip, back to pending
     *   - "generate": every narration clip - handleDeleteBookAudio's action
     *
     * The paragraph passes accept ?fromChapter=<idx> to reset only chapters at
     * or after that index instead of the whole book; the other passes reject it.
     *
     * Doesn't cancel an in-flight run of the same pass, which would set its
     * flag again as it finishes - the Speakers page disables a reset while its
     * pass is running. 200 {"invalidated": n}, n = paragraphs whose audio was
     * deleted (0 for the music/lighting/generate resets).
     */
    @POST("api/books/{id}/reset/{pass}")
    suspend fun resetPass(
        @Path("id") id: String,
        @Path("pass") pass: ResetPass,
        @Query("fromChapter") fromChapter: String? = null,
    ): InvalidatedResponseDto

