    ): ResponseBody

    /**
     * handleRegeneratePreset is the built-in-preset equivalent of
     * handleRegenerateCustomVoicePreset - force re-renders id's reference clip
     * via VoiceDesign from its fixed, compiled-in recipe (built-ins are never
     * stored in the DB - see internal/voices' own doc comment - but their
     * rendered reference clip is cached on disk under their own id exactly
     * like a custom preset's, via the same internal/voicerefs). Useful to
     * retry after tts-service was briefly down when a preset's clip was first
     * needed, without waiting for the next arbitrary request that happens to
     * call EnsureFile on it.
     */
    @POST("api/voices/presets/{id}/regenerate")
    suspend fun regeneratePreset(
        @Path("id") id: String,
    ): VoicePresetDto

    /**
     * handleTestPreset is the built-in-preset equivalent of
     * handleTestCustomVoicePreset, so the same "hear it on other text" preview
     * works for curated presets too, not just custom ones.
     */
    @Streaming
    @POST("api/voices/presets/{id}/test")
    suspend fun testPreset(
        @Path("id") id: String,
        @Body body: TestVoiceRequestDto,
    ): ResponseBody

    /**
     * handleRoleVariantAudio serves the reference clip of a role voice's
     * numbered sibling (narration.MemberVoice - a derived preset id, with no
     * stored preset to look up) - the Speakers page's per-number preview. 404
     * until it's been rendered.
     */
    @Streaming
    @GET("api/voices/role-variants/{presetId}/audio")
    suspend fun roleVariantAudio(
        @Path("presetId") presetId: String,
    ): ResponseBody

    /**
     * handleVariantAudio serves one emotion variant of a voice preset's
     * reference clip (see voicerefs.EnsureVariantFile) - the Speakers page's
     * per-emotion preview. 404 until it's been rendered.
     */
    @Streaming
    @GET("api/voices/variants/{presetId}/{emotion}/audio")
    suspend fun variantAudio(
        @Path("presetId") presetId: String,
        @Path("emotion") emotion: String,
    ): ResponseBody
}
